        for e in c['evidence'][1:]:assert e['profile']['peak_private_bytes']<=8*1024**3 and e['profile']['seconds']<=600
        assert len(read('reachability.json'))==25 and all(j['passed'] for j in read('reachability.json'))
        cases=read('cases/result.json');assert cases['result']=='PASS';full=read('full-cases.json');assert full['result']=='PASS' and len(full['cases'])==360
        mutants=read('mutants.json');assert len(mutants)==12 and all(j['result']=='DETECTED_BY_BRIDGE' for j in mutants)
        integration=read('integration.json');assert integration['whole_status']==0 and not any(j['problems'] for j in integration['cases']) and all(not any(j['fallbacks']) for j in integration['scenario_audits'])
        host=read('host.json');assert host['result']=='PASS' and host['check']['passed']
        c['evidence'] += [row('Actual-C HUD scalar slices','C','python verif/hud_cases.py',cases['stdout'].splitlines()[0],cases['scope']),row('Complete digit and bar scalar domains','A','python verif/hud_cases.py','; '.join(cases['stdout'].splitlines()[1:]),cases['scope']),row('Full RAM/device/ABI and abnormal prefixes','C','python verif/hud_full_cases.py','PASS360 pairs',full['scope']),row('Private output/projection mutants','C','python verif/hud_mutants.py','PASS12 DETECTED_BY_BRIDGE','Glyph, cursor, sentinel/comparison, cap/priority/fare, signed bar/mask/span, leftover effect and working projection. Compile failure does not count.'),row('L0 to actual composed handlers','C','python verif/hud_integration.py --whole --local-reference','PASS'+str(len(integration['cases']))+' comparisons','Seven maintained suites and inherited VGA cases, normal/poison; full RAM, device, ABI/defined flags and ordered IO.'),row('Whole-game counts and scratch promotion','D','python verif/hud_integration.py --whole --local-reference; python verif/hud_host.py','PASS20 scenarios, rainy witness, native host20 scenarios and256-frame smoke','Committed008149c plus owned primitive/HUD overlay; no concurrent input/video files.')]
        c['entry_order']=NAMES;c['scenario_entry_counts']=integration['scenario_audits'];c['scratch_acceptance']=dict(baseline=host['baseline_revision'],linked_units=[u['component'] for u in host['build']['linked_units']]);c['proposed_status']='migrated'
        c['negative_results']=dict(reachability='25/25 final-comparison controls intentionally fail only at their specified assertion. See reachability.json.',diagnostics='Initial kernel preprocessing lacked stdlib and a modeled memset body; corrected with explicit scoped normalization. Unused cut labels are suppressed only in compiled harnesses. No final timeout or memory cap is credited as proof.')
        from render_primitives_shells import FILES as PRIMITIVE_FILES
