        c['verification_input_hashing']='sha256-lf-text';c['verification_inputs']={p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes().replace(b'\r\n',b'\n')).hexdigest() for p in locked if p.is_file()}
